			const originMatch = cleanBase.match(/^(https?:\/\/[^/]+)(\/.*)$/i);
			if (originMatch && /[^\x21-\x7E]/.test(originMatch[2])) cleanBase = originMatch[1] + this._encodePathSegments(originMatch[2]);
