			base = base.replace(/\/api\/resolve\/?.*$/, "").replace(/\/+$/, "");
			const token = customToken || config.gatewayToken || "dev";
			const healthUrl = `${base}/health`;
			let healthOk = false;
			try {
				const hRes = await fetchWithTransport(healthUrl, { timeout: 4e3 });
				if (hRes.status >= 200 && hRes.status < 400) healthOk = true;
			} catch (_) {}
			const playUrl = `${base}/v1/${token}/play/STARS-256.m3u8`;
